'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createStore } = require('../src/store');
const { STATUS, createTicket, resolveTicket } = require('../src/tickets');
const portal = require('../src/portal');

const DAY = 24 * 60 * 60 * 1000;
const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
const acme = { id: 7, orgId: 1 };
const globex = { id: 9, orgId: 2 };

function resolvedTicket(store, { orgId = 1, resolve = true } = {}) {
  const t = createTicket(store, { orgId, customerId: 7, subject: 'Printer', body: 'x', now: at(0) });
  if (resolve) resolveTicket(store, t.id, 41, { now: at(1) });
  return t;
}

test('a customer rates a resolved ticket of their organisation, and it is stored with score and time', () => {
  const store = createStore();
  const t = resolvedTicket(store);
  const rated = portal.rateTicket(store, acme, t.id, 4, { now: at(2) });
  assert.equal(rated.rating, 4);
  assert.equal(rated.rated_at, at(2).toISOString());
  assert.equal(store.getTicket(t.id).rating, 4);
});

test('a score that is not a whole number from 1 to 5 is refused and nothing is stored', () => {
  const store = createStore();
  const t = resolvedTicket(store);
  for (const bad of [0, 6, 3.5, -1, NaN, '4', null, undefined]) {
    assert.throws(() => portal.rateTicket(store, acme, t.id, bad), /whole number from 1 to 5/, String(bad));
  }
  assert.equal(store.getTicket(t.id).rating, null);
});

test('an open or pending ticket cannot be rated', () => {
  const store = createStore();
  const open = resolvedTicket(store, { resolve: false });
  assert.throws(() => portal.rateTicket(store, acme, open.id, 5), /cannot rate a open ticket/);
  store.updateTicket(open.id, { status: STATUS.PENDING });
  assert.throws(() => portal.rateTicket(store, acme, open.id, 5), /cannot rate a pending ticket/);
});

test('a second rating is refused and the first stays', () => {
  const store = createStore();
  const t = resolvedTicket(store);
  portal.rateTicket(store, acme, t.id, 4, { now: at(2) });
  assert.throws(() => portal.rateTicket(store, acme, t.id, 1, { now: at(3) }), /already rated/);
  const kept = store.getTicket(t.id);
  assert.equal(kept.rating, 4);
  assert.equal(kept.rated_at, at(2).toISOString());
});

test('another organisation gets the answer for a ticket that does not exist, whatever the score or status', () => {
  const store = createStore();
  const t = resolvedTicket(store);
  const open = resolvedTicket(store, { resolve: false });
  const missing = portal.rateTicket(store, globex, 999, 4);
  assert.equal(missing, null);
  assert.equal(portal.rateTicket(store, globex, t.id, 4), null);
  assert.equal(portal.rateTicket(store, globex, t.id, 99), null);
  assert.equal(portal.rateTicket(store, globex, open.id, 4), null);
  assert.equal(store.getTicket(t.id).rating, null);
});
```

