'use strict';
// Nightly. For each agent, how many ratings their tickets received in the past seven days and the average score.
// The agent is the ticket's owner when the job runs; tickets without an owner are left out.
const { ownerOf } = require('../tickets');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function weeklyCsat(store, { now = new Date() } = {}) {
  const day = now.toISOString().slice(0, 10);
  const totals = new Map();
  for (const t of store.listTickets()) {
    if (t.rating == null) continue;
    if (now.getTime() - new Date(t.rated_at).getTime() > WINDOW_DAYS * DAY) continue;
    const agent = ownerOf(t);
    if (!agent) continue;
    const sum = totals.get(agent) || { ratings: 0, total: 0 };
    sum.ratings += 1;
    sum.total += t.rating;
    totals.set(agent, sum);
  }
  const rows = [...totals].map(([agent_id, s]) => ({ agent_id, day, ratings: s.ratings, average: Math.round((s.total / s.ratings) * 100) / 100 }));
  for (const row of rows) store.saveWeeklySummary(row);
  return rows;
}

module.exports = { weeklyCsat, WINDOW_DAYS };
```

